import java.math.BigDecimal;
import java.math.RoundingMode;
import java.math.MathContext;

public class test_cartao {
    public static void main(String[] args) {
        BigDecimal total = new BigDecimal("425.30");
        Integer parcelas = 6;
        BigDecimal TAXA_JUROS = new BigDecimal("0.0199");

        BigDecimal taxa = TAXA_JUROS;
        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxa);

        System.out.println("Total: " + total);
        System.out.println("Taxa: " + taxa);
        System.out.println("1 + taxa: " + umMaisTaxa);

        BigDecimal potencia = umMaisTaxa.pow(parcelas, MathContext.DECIMAL128);
        System.out.println("(1 + taxa)^n: " + potencia);

        BigDecimal inversa = BigDecimal.ONE.divide(potencia, 10, RoundingMode.HALF_EVEN);
        System.out.println("1 / (1 + taxa)^n: " + inversa);

        BigDecimal denominador = BigDecimal.ONE.subtract(inversa);
        System.out.println("1 - 1/(1 + taxa)^n: " + denominador);

        BigDecimal numerador = total.multiply(taxa);
        System.out.println("total × taxa: " + numerador);

        BigDecimal parcela = numerador.divide(denominador, 10, RoundingMode.HALF_EVEN);
        System.out.println("Parcela (10 decimais): " + parcela);

        BigDecimal parcelaArredondada = parcela.setScale(2, RoundingMode.HALF_EVEN);
        System.out.println("Parcela (2 decimais): " + parcelaArredondada);

        BigDecimal totalFinal = parcelaArredondada.multiply(new BigDecimal(parcelas));
        System.out.println("Total final (6 × parcela): " + totalFinal);

        BigDecimal ajuste = totalFinal.subtract(total);
        System.out.println("Ajuste: " + ajuste);
    }
}
